      "k": "quiz",
      "p": "B4-adt",
      "s": "quiz",
      "h": 1,
      "m": 1,
      "q": "State the order in which a pre-order traversal visits the nodes.",
      "a": [
        "Node (root), then the left subtree, then the right subtree."
      ],
      "c": "State",
      "id": "ad79ca08c",
      "u": "B4",
      "n": "B4-adt.bst",
      "f": "pre order|order traversal",
