      "p": "B2-control",
      "s": "selection",
      "h": 0,
      "m": 2,
      "q": "Construct Python code that outputs \"Pass\" if mark is 50 or more, and \"Fail\" otherwise.",
      "a": [
        "if mark &gt;= 50: print(\"Pass\")",
        "else: print(\"Fail\")"
      ],
      "t": "selection",
      "c": "Construct",
      "id": "e8a727999",
      "u": "B2",
