      "p": "A4-models",
      "s": "metrics",
      "h": 1,
      "m": 2,
      "q": "Distinguish between a false positive and a false negative, using a medical test as an example.",
      "a": [
        "A false positive is a case predicted positive that is actually negative, e.g. a healthy patient told they have the disease;",
        "a false negative is a case predicted negative that is actually positive, e.g. a patient with the disease told they are healthy."
      ],
      "t": "confusion-matrix",
      "c": "Distinguish",
      "id": "791de3d4e",
      "u": "A4",
